90	## Edit 1.2 — Muon 2D-weight table (constant array) → formula
91	
92	The `__device__ __constant__ DecMuon2D kDecMuon2D[...]` brace-list cannot be a
93	loop-filled 195-entry table at L=48. Replace it with a `constexpr`
94	`dec_muon_2d(mi)` accessor returning the same `DecMuon2D` by value, and a
95	formula-based `dec_is_muon_2d(t)`. `kDecNumMuon2D = 4*L+3`. The Muon driver loop
96	in fused_decoder_megakernel.cuh is updated in Edit 2.6 to call `dec_muon_2d(mi)`
97	instead of indexing the (now-removed) array.
98	
99	OLD:
100	```
101	constexpr int kDecNumMuon2D = 11;
102	struct DecMuon2D { int tidx; int rows; int cols; };
103	__device__ __constant__ DecMuon2D kDecMuon2D[kDecNumMuon2D] = {
104	    { 0, dec::kVocab,  dec::kD     },   // tok.weight          [99,128]
105	    { 1, dec::kSeq,    dec::kD     },   // pos.weight          [4,128]
106	    { 2, 3*dec::kD,    dec::kD     },   // L0 in_proj_weight   [384,128]
107	    { 4, dec::kD,      dec::kD     },   // L0 out_proj.weight  [128,128]
108	    {10, dec::kDff,    dec::kD     },   // L0 ff.0.weight      [512,128]
109	    {12, dec::kD,      dec::kDff   },   // L0 ff.2.weight      [128,512]
110	    {14, 3*dec::kD,    dec::kD     },   // L1 in_proj_weight   [384,128]
111	    {16, dec::kD,      dec::kD     },   // L1 out_proj.weight  [128,128]
112	    {22, dec::kDff,    dec::kD     },   // L1 ff.0.weight      [512,128]
113	    {24, dec::kD,      dec::kDff   },   // L1 ff.2.weight      [128,512]
114	    {28, dec::kVocab,  dec::kD     },   // out.weight          [99,128]
115	};
116	// Is tensor index `t` one of the Muon 2D matrices (orthogonalized in P2.7)? P3
117	// uses this to route ONLY the 1D / non-2D weights to the AdamW aux tail for Muon.
118	__device__ __forceinline__ bool dec_is_muon_2d(int t) {
119	    #pragma unroll
120	    for (int mi = 0; mi < kDecNumMuon2D; ++mi) if (kDecMuon2D[mi].tidx == t) return true;
121	    return false;
122	}
123	```
124	
125	NEW:
126	```
127	// kDecNumMuon2D = tok + pos + 4 weights/layer (in_proj,out_proj,ff0,ff2) + head.out
128	//   = 2 + 4*L + 1  (= 11 at L=2). The table is now a FORMULA (dec_muon_2d) — a
129	// __device__ __constant__ array can't be loop-filled to 195 entries at L=48.
130	constexpr int kDecNumMuon2D = 2 + 4 * dec::kLayers + 1;
131	struct DecMuon2D { int tidx; int rows; int cols; };
132	// The mi-th Muon 2D matrix (tensor index + rows/cols), L-general. Dense order:
133	//   mi=0 tok[V,d]; mi=1 pos[seq,d];
134	//   mi∈[2,2+4L): li=(mi-2)/4, kind=(mi-2)%4 →
135	//     kind0 in_proj  tidx 2 +12li  [3d,d]
136	//     kind1 out_proj tidx 4 +12li  [d, d]
137	//     kind2 ff0      tidx 10+12li  [dff,d]
138	//     kind3 ff2      tidx 12+12li  [d, dff]
139	//   mi=2+4L head out.weight tidx 2+12L+2 [V,d].
140	// At L=2 reproduces the old kDecMuon2D[11] EXACTLY (tidx {0,1,2,4,10,12,14,16,22,24,28}).
141	__host__ __device__ __forceinline__ DecMuon2D dec_muon_2d(int mi) {
142	    if (mi == 0)                         return { 0, dec::kVocab, dec::kD };   // tok
143	    if (mi == 1)                         return { 1, dec::kSeq,   dec::kD };   // pos
144	    if (mi == 2 + 4 * dec::kLayers)      return { 2 + 12 * dec::kLayers + 2, dec::kVocab, dec::kD }; // head.out
145	    const int li   = (mi - 2) / 4;
146	    const int kind = (mi - 2) % 4;
147	    if (kind == 0) return { 2  + 12 * li, 3 * dec::kD, dec::kD   };  // in_proj
148	    if (kind == 1) return { 4  + 12 * li, dec::kD,     dec::kD   };  // out_proj
149	    if (kind == 2) return { 10 + 12 * li, dec::kDff,   dec::kD   };  // ff0
150	    return            { 12 + 12 * li, dec::kD,     dec::kDff };      // ff2
151	}
152	// Is tensor index `t` a Muon 2D matrix (orthogonalized in P2.7)? P3 routes only
153	// the 1D / non-2D weights to the AdamW aux tail. Closed-form (no table scan):
154	//   t∈{0,1} (tok/pos), OR t==head.out (2+12L+2), OR a per-layer 2D weight
155	//   (t∈[2,2+12L) and (t-2)%12 ∈ {0,2,8,10} = in_w/out_w/ff0_w/ff2_w).
156	__device__ __host__ __forceinline__ bool dec_is_muon_2d(int t) {
157	    if (t == 0 || t == 1) return true;
158	    if (t == 2 + 12 * dec::kLayers + 2) return true;       // head out.weight
159	    if (t >= 2 && t < 2 + 12 * dec::kLayers) {
160	        const int r = (t - 2) % 12;
161	        return (r == 0 || r == 2 || r == 8 || r == 10);
162	    }
163	    return false;
164	}
165	```
