477	## Edit 1.11 — `dectc_dw_biases` (signature + `pre[10]` + the two `s<9`/`t<9` + `pre[9]`)
478	
479	`pre[10]` is a `[#specs + 1]` exclusive-prefix array → `pre[kDecNumDwSpecs + 1]`.
480	`pre[9]` (= total) → `pre[kDecNumDwSpecs]`. The `#pragma unroll` directives are
481	KEPT (byte-identical at L=2; they fully unroll a tiny 1-line prefix body — valid,
482	just larger code at L=48; the bodies are trivial).
483	
484	OLD:
485	```
486	__device__ __forceinline__ void dectc_dw_biases(
487	        const DecDwSpec spec[9], float* __restrict__ grad, int cta, int nCTA) {
488	    // exclusive prefix of Nout across the 9 specs → total bias-output count.
489	    int pre[10];
490	    pre[0] = 0;
491	    #pragma unroll
492	    for (int s = 0; s < 9; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
493	    const int total = pre[9];
494	    const int stride = nCTA * blockDim.x;
495	    for (int go = cta * blockDim.x + threadIdx.x; go < total; go += stride) {
496	        // decode global output index → (spec s, local row o). 9 specs → linear scan.
497	        int s = 0;
498	        #pragma unroll
499	        for (int t = 0; t < 9; ++t) if (go >= pre[t + 1]) s = t + 1;
500	        const DecDwSpec& sp = spec[s];
501	```
502	
503	NEW:
504	```
505	__device__ __forceinline__ void dectc_dw_biases(
506	        const DecDwSpec spec[kDecNumDwSpecs], float* __restrict__ grad, int cta, int nCTA) {
507	    // exclusive prefix of Nout across the specs → total bias-output count.
508	    int pre[kDecNumDwSpecs + 1];
509	    pre[0] = 0;
510	    #pragma unroll
511	    for (int s = 0; s < kDecNumDwSpecs; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
512	    const int total = pre[kDecNumDwSpecs];
513	    const int stride = nCTA * blockDim.x;
514	    for (int go = cta * blockDim.x + threadIdx.x; go < total; go += stride) {
515	        // decode global output index → (spec s, local row o). #specs → linear scan.
516	        int s = 0;
517	        #pragma unroll
518	        for (int t = 0; t < kDecNumDwSpecs; ++t) if (go >= pre[t + 1]) s = t + 1;
519	        const DecDwSpec& sp = spec[s];
520	```
